style.css:
@-moz-document domain("youtube.com") {
:root {
    --vhs-green: #9cff9c;
    --vhs-red: #ff6b6b;
    --bg: #020202;
  }

  body, ytd-app {
    background: var(--bg) !important;
    color: #e0e0e0 !important;
    font-family: monospace !important;
  }

  /* ===== VHS GIF BACKGROUND ===== */
  ytd-app::before {
    content: "";
    position: fixed;
    inset: 0;
    background: url("https://i.pinimg.com/originals/f2/ff/82/f2ff82037fcc5a2305be0ee82d79e893.gif") center / cover no-repeat;
    opacity: 0.15;
    filter: blur(2px) brightness(0.5) contrast(1.4) saturate(0.6);
    pointer-events: none;
    z-index: -2;
  }

  /* ===== VIGNETTE ===== */
  body::before {
    content: "";
    position: fixed;
    inset: 0;
    background: radial-gradient(circle, transparent 55%, rgba(0,0,0,0.75) 100%);
    pointer-events: none;
    z-index: 9998;
  }

  /* ===== SCANLINES ===== */
  body::after {
    content: "";
    position: fixed;
    inset: 0;
    background: repeating-linear-gradient(
      to bottom,
      rgba(255,255,255,0.05),
      rgba(255,255,255,0.05) 1px,
      transparent 1px,
      transparent 4px
    );
    pointer-events: none;
    mix-blend-mode: overlay;
    opacity: 0.35;
    z-index: 9999;
  }

  /* ===== VHS FLICKER ===== */
  body {
    animation: vhs-flicker 2.8s infinite;
  }

  @keyframes vhs-flicker {
    0%, 100% { opacity: 1; }
    47% { opacity: 0.96; }
    50% { opacity: 0.85; }
    53% { opacity: 1; }
  }

  /* ===== VIDEO CARDS ===== */
  ytd-rich-item-renderer {
    background: #050505 !important;
    border-radius: 10px;
    box-shadow: 0 0 20px rgba(0,0,0,0.9);
  }

  /* ===== VHS TEXT (RGB SPLIT) ===== */
  #video-title {
    position: relative;
    color: #ffffff !important;
    text-shadow:
      -2px 0 var(--vhs-red),
       2px 0 var(--vhs-green);
    animation: vhs-text 1.6s infinite;
  }

  @keyframes vhs-text {
    0%   { text-shadow: -2px 0 var(--vhs-red), 2px 0 var(--vhs-green); }
    25%  { text-shadow: -4px 0 var(--vhs-red), 3px 0 var(--vhs-green); }
    50%  { text-shadow: -1px 0 var(--vhs-red), 1px 0 var(--vhs-green); }
    75%  { text-shadow: -5px 0 var(--vhs-red), 4px 0 var(--vhs-green); }
    100% { text-shadow: -2px 0 var(--vhs-red), 2px 0 var(--vhs-green); }
  }

  /* ===== TRACKING GLITCH (HORIZONTAL JITTER) ===== */
  ytd-app {
    animation: tracking 6s infinite;
  }

  @keyframes tracking {
    0% { transform: translateX(0); }
    92% { transform: translateX(0); }
    93% { transform: translateX(-6px); }
    94% { transform: translateX(6px); }
    95% { transform: translateX(-4px); }
    96% { transform: translateX(4px); }
    97% { transform: translateX(0); }
  }

  /* ===== STATIC NOISE ===== */
  ytd-app::after {
    content: "";
    position: fixed;
    inset: 0;
    background-image:
      repeating-radial-gradient(circle,
        rgba(255,255,255,0.04) 0,
        rgba(255,255,255,0.04) 1px,
        transparent 1px,
        transparent 3px);
    opacity: 0.12;
    pointer-events: none;
    z-index: 9997;
  }
}
